@staticmethod
def _extract_review_json(raw: str) -> dict[str, Any]:
    """Extrahiert das letzte gültige Reviewer-Urteil aus gemischter Modellausgabe."""
    text = str(raw or "").strip()
    valid: list[dict[str, Any]] = []

    def accept(obj: Any) -> None:
        if not isinstance(obj, dict):
            return
        verdict = str(obj.get("verdict", "")).strip().upper()
        if verdict in ("PASS", "FIX_REQUIRED"):
            valid.append(obj)

    try:
        accept(AgentController._extract_json(text))
    except Exception:
        pass

    depth = 0
    start: int | None = None
    in_string = False
    escaped = False

    for idx, char in enumerate(text):
        if in_string:
            if escaped:
                escaped = False
            elif char == "\\":
                escaped = True
            elif char == '"':
                in_string = False
            continue
        if char == '"':
            in_string = True
            continue
        if char == "{":
            if depth == 0:
                start = idx
            depth += 1
            continue
        if char == "}" and depth:
            depth -= 1
            if depth == 0 and start is not None:
                candidate = text[start : idx + 1]
                for strict in (True, False):
                    try:
                        accept(json.loads(candidate, strict=strict))
                        break
                    except json.JSONDecodeError:
                        continue
                start = None

    if valid:
        return valid[-1]
    raise AgentError("Reviewer-Antwort enthält kein gültiges PASS/FIX_REQUIRED-JSON-Objekt.")

def _review_json_call(
    self,
    messages: list[dict[str, str]],
    max_tokens: int,
    *,
    stage: str,
) -> dict[str, Any]:
    """Ein fachlicher Review plus höchstens ein reiner Format-Recovery-Versuch."""
    if self.reviewer_client is None:
        raise AgentError("Reviewer-Client ist nicht aktiv.")

    raw = self.reviewer_client.complete(messages, max_tokens=max_tokens)

    for attempt in (1, 2):
        try:
            return self._extract_review_json(raw)
        except Exception as exc:
            safe_raw = redact(str(raw or ""))
            raw_hash = hashlib.sha256(
                str(raw or "").encode("utf-8", errors="replace")
            ).hexdigest()
            self.logger.emit(
                "review",
                "Reviewer-Ausgabeformat ungültig."
                + (" Format-Recovery wird versucht." if attempt == 1 else ""),
                error_code="REVIEW_OUTPUT_INVALID",
                stage=stage,
                attempt=attempt,
                parse_error=redact(str(exc)),
                raw_chars=len(str(raw or "")),
                raw_sha256=raw_hash,
                finish_reason=str(
                    getattr(self.reviewer_client, "last_finish_reason", "") or ""
                ),
                raw_excerpt=truncate(safe_raw, REVIEW_RAW_DIAGNOSTIC_CHARS),
            )

            if attempt == 2:
                raise AgentError(
                    "REVIEW_OUTPUT_INVALID: "
                    + stage
                    + ": Reviewer lieferte auch nach Format-Recovery kein "
                      "gültiges PASS/FIX_REQUIRED-JSON-Objekt."
                ) from exc

            repair_messages = [
                {"role": "system", "content": REVIEW_FORMAT_REPAIR_SYSTEM_PROMPT},
                {
                    "role": "user",
                    "content": (
                        "VORHERIGE REVIEWER-ANTWORT:\n"
                        + truncate(safe_raw, REVIEW_RAW_DIAGNOSTIC_CHARS)
                    ),
                },
            ]
            raw = self.reviewer_client.complete(
                repair_messages,
                max_tokens=REVIEW_FORMAT_REPAIR_MAX_OUTPUT_TOKENS,
            )

    raise AgentError("REVIEW_OUTPUT_INVALID: unerreichbarer Format-Recovery-Zustand.")

